JavaScript-Code:

```javascript
// Chatbot messages
const botMessages = [
  "Hi! How can I assist you today?",
  "That's great to hear! Let me know if you need any help."
];

// User messages
const userMessages = [
  "I'm trying to find a product on your website.",
  "Can you recommend something based on my preferences?"
];

// Render chat messages in the modal
function renderChatMessages() {
  const chatContainer = document.querySelector(".chat-container");

  // Clear existing chat messages
  chatContainer.innerHTML = "";

  // Loop through messages and render them
  for (let I = 0; I < botMessages.length; i++) {
    const message = document.createElement("div");
    message.className = "chat-message";
    message.innerHTML = `
      <div class="chat-message__text ${i % 2 === 0 ? "user" : "bot"}">
        ${i % 2 === 0 ? userMessages[i] : botMessages[i]}
      </div>
    `;
    chatContainer.appendChild(message);
  }
}

// Open the modal when button is clicked
const openModalButton = document.getElementById("open-modal");
openModalButton.addEventListener("click", () => {
  const modal = document.getElementById("modal");
  modal.style.display = "block";
  renderChatMessages();
});

// Close the modal when the user clicks anywhere outside of it
